函数代码：
```javascript
function isPalindrome(s) {
    // 空串视为回文
    if (s === '') {
        return true;
    }

    // 反转字符串并与原字符串比较（区分大小写）
    const reversed = s.split('').reverse().join('');
    return s === reversed;
}
